INSERT INTO FAQ (MaFAQ, CauHoi, CauTraLoi, NhomChuDe, MaTK_QTVHT) VALUES ('FAQ001', N'Làm thế nào để thay đổi mật khẩu tài khoản?', N'Bạn có thể vào Cài đặt > Tài khoản > Đổi mật khẩu. Vui lòng nhập mật khẩu hiện tại và mật khẩu mới để xác nhận.', N'Tài khoản', 'TK001');
INSERT INTO FAQ (MaFAQ, CauHoi, CauTraLoi, NhomChuDe, MaTK_QTVHT) VALUES ('FAQ002', N'Làm sao để xem phim trên màn hình Tivi (Smart TV)?', N'Ứng dụng Nighthub hiện đã hỗ trợ cài đặt trên các nền tảng WebOS, Tizen và Android TV. Hoặc bạn có thể sử dụng tính năng Cast từ điện thoại.', N'Ứng dụng', 'TK001');
INSERT INTO FAQ (MaFAQ, CauHoi, CauTraLoi, NhomChuDe, MaTK_QTVHT) VALUES ('FAQ003', N'Hướng dẫn khắc phục sự cố tải video chậm, giật lag', N'Vui lòng kiểm tra lại kết nối mạng của bạn, đảm bảo tốc độ tối thiểu 5Mbps. Bạn cũng có thể thử đổi máy chủ phát trong phần tuỳ chọn trình phát video.', N'Lỗi ứng dụng', 'TK001');
INSERT INTO FAQ (MaFAQ, CauHoi, CauTraLoi, NhomChuDe, MaTK_QTVHT) VALUES ('FAQ004', N'Cách hủy gia hạn gói VIP tự động?', N'Vào Cài đặt > Gói cước & Thanh toán, cuộn xuống phần Quản lý Gói và chọn "Hủy gia hạn". Bạn vẫn được dùng đến hết chu kỳ hiện tại.', N'Gói cước', 'TK001');
INSERT INTO FAQ (MaFAQ, CauHoi, CauTraLoi, NhomChuDe, MaTK_QTVHT) VALUES ('FAQ005', N'Tôi không tìm thấy câu hỏi phù hợp với vấn đề của mình?', N'Đừng lo! Bạn có thể nhấn vào biểu tượng Chatbot ở góc phải màn hình để được hỗ trợ trực tuyến 24/7, hoặc sử dụng các thông tin liên hệ ở khối bên dưới.', N'Khác', 'TK001');
INSERT INTO FAQ (MaFAQ, CauHoi, CauTraLoi, NhomChuDe, MaTK_QTVHT) VALUES ('FAQ006', N'Làm thế nào để đăng ký tài khoản?', N'Bạn nhấn vào nút Đăng ký ở góc trên bên phải, nhập email và mật khẩu.', N'Tài khoản', 'TK001');
INSERT INTO FAQ (MaFAQ, CauHoi, CauTraLoi, NhomChuDe, MaTK_QTVHT) VALUES ('FAQ007', N'Tôi quên mật khẩu thì phải làm sao?', N'Nhấn vào "Quên mật khẩu" tại trang đăng nhập và làm theo hướng dẫn gửi tới email.', N'Tài khoản', 'TK001');
INSERT INTO FAQ (MaFAQ, CauHoi, CauTraLoi, NhomChuDe, MaTK_QTVHT) VALUES ('FAQ008', N'Gói VIP có quyền lợi gì?', N'Xem phim không quảng cáo, chất lượng 4K và truy cập kho phim độc quyền.', N'Gói cước', 'TK001');
INSERT INTO FAQ (MaFAQ, CauHoi, CauTraLoi, NhomChuDe, MaTK_QTVHT) VALUES ('FAQ009', N'Nền tảng hỗ trợ những thiết bị nào?', N'Hỗ trợ Web, Smart TV, Android và iOS.', N'Ứng dụng', 'TK001');
INSERT INTO FAQ (MaFAQ, CauHoi, CauTraLoi, NhomChuDe, MaTK_QTVHT) VALUES ('FAQ010', N'Tôi có thể chia sẻ tài khoản không?', N'Gói VIP cho phép đăng nhập tối đa trên 3 thiết bị cùng lúc.', N'Tài khoản', 'TK001');
INSERT INTO FAQ (MaFAQ, CauHoi, CauTraLoi, NhomChuDe, MaTK_QTVHT) VALUES ('FAQ011', N'Làm sao để đổi thông tin cá nhân?', N'Vào mục Hồ sơ cá nhân để cập nhật tên, ngày sinh và ảnh đại diện.', N'Tài khoản', 'TK001');
INSERT INTO FAQ (MaFAQ, CauHoi, CauTraLoi, NhomChuDe, MaTK_QTVHT) VALUES ('FAQ012', N'Làm sao để tìm kiếm phim theo thể loại?', N'Sử dụng bộ lọc ở trang chủ hoặc thanh tìm kiếm phía trên.', N'Ứng dụng', 'TK001');
INSERT INTO FAQ (MaFAQ, CauHoi, CauTraLoi, NhomChuDe, MaTK_QTVHT) VALUES ('FAQ013', N'Tôi có thể tải phim về xem ngoại tuyến không?', N'Tính năng tải xuống khả dụng trên ứng dụng di động cho thành viên VIP.', N'Ứng dụng', 'TK001');
INSERT INTO FAQ (MaFAQ, CauHoi, CauTraLoi, NhomChuDe, MaTK_QTVHT) VALUES ('FAQ014', N'Làm sao để lưu phim vào danh sách yêu thích?', N'Nhấn vào biểu tượng trái tim hoặc "Thêm vào danh sách" tại trang thông tin phim.', N'Ứng dụng', 'TK001');
INSERT INTO FAQ (MaFAQ, CauHoi, CauTraLoi, NhomChuDe, MaTK_QTVHT) VALUES ('FAQ015', N'Làm sao để báo cáo bình luận vi phạm?', N'Nhấn vào dấu ba chấm bên cạnh bình luận và chọn "Báo cáo".', N'Bảo mật', 'TK001');
INSERT INTO FAQ (MaFAQ, CauHoi, CauTraLoi, NhomChuDe, MaTK_QTVHT) VALUES ('FAQ016', N'Các phương thức thanh toán là gì?', N'Hỗ trợ thẻ tín dụng, ví điện tử MoMo, ZaloPay và chuyển khoản.', N'Gói cước', 'TK001');
INSERT INTO FAQ (MaFAQ, CauHoi, CauTraLoi, NhomChuDe, MaTK_QTVHT) VALUES ('FAQ017', N'Tôi có được hoàn tiền khi hủy gói không?', N'Chính sách không áp dụng hoàn tiền cho các gói cước đã kích hoạt.', N'Gói cước', 'TK001');
INSERT INTO FAQ (MaFAQ, CauHoi, CauTraLoi, NhomChuDe, MaTK_QTVHT) VALUES ('FAQ018', N'Làm sao để thay đổi ngôn ngữ phụ đề?', N'Nhấn vào biểu tượng bánh răng trong trình phát video và chọn Phụ đề.', N'Ứng dụng', 'TK001');
INSERT INTO FAQ (MaFAQ, CauHoi, CauTraLoi, NhomChuDe, MaTK_QTVHT) VALUES ('FAQ019', N'Phim có hỗ trợ thuyết minh không?', N'Một số phim sẽ có tùy chọn Thuyết minh trong phần cài đặt âm thanh.', N'Ứng dụng', 'TK002');
INSERT INTO FAQ (MaFAQ, CauHoi, CauTraLoi, NhomChuDe, MaTK_QTVHT) VALUES ('FAQ020', N'Yêu cầu phim mới ở đâu?', N'Bạn có thể gửi yêu cầu thông qua mục "Góp ý" trong phần hỗ trợ.', N'Khác', 'TK002');
INSERT INTO FAQ (MaFAQ, CauHoi, CauTraLoi, NhomChuDe, MaTK_QTVHT) VALUES ('FAQ021', N'Làm sao để nhận thông báo phim mới?', N'Bật thông báo ứng dụng hoặc đăng ký nhận tin qua email trong cài đặt.', N'Tài khoản', 'TK002');
INSERT INTO FAQ (MaFAQ, CauHoi, CauTraLoi, NhomChuDe, MaTK_QTVHT) VALUES ('FAQ022', N'Tại sao tôi không xem được phim ở nước ngoài?', N'Do giới hạn bản quyền, một số nội dung chỉ khả dụng tại Việt Nam.', N'Bảo mật', 'TK002');
INSERT INTO FAQ (MaFAQ, CauHoi, CauTraLoi, NhomChuDe, MaTK_QTVHT) VALUES ('FAQ023', N'Làm sao để liên hệ trực tiếp hỗ trợ?', N'Gọi hotline 1900xxxx hoặc gửi email về support@nighthub.com.', N'Khác', 'TK002');
