INSERT INTO BAO_CAO_VI_PHAM (MaBC, LyDo, NgayTao, MaBL, MaHoSoGui) VALUES ('BC005', N'Bình luận nói phim có cảnh bạo lực không phù hợp trẻ em nhưng cách diễn đạt khiến người khác hiểu lầm nền tảng đang chiếu nội dung bạo lực cho trẻ em. Thông tin sai lệch.', TO_TIMESTAMP('2026-05-16 06:00:00','YYYY-MM-DD HH24:MI:SS'), 'BL018', 'HoSo003');
INSERT INTO HE_THONG_DANH_DAU (MaHTDD, DoTinCay, NgayDanhDau, LoaiDanhDau, GhiChu, MaBL) VALUES ('HTDD001', 97.50, TO_DATE('06/05/2026','DD/MM/YYYY'), 'spam', N'Phát hiện chứa URL bên ngoài (phimhay.xyz). Nội dung mang tính quảng cáo thương mại, không liên quan tới đánh giá phim.', 'BL006');
INSERT INTO HE_THONG_DANH_DAU (MaHTDD, DoTinCay, NgayDanhDau, LoaiDanhDau, GhiChu, MaBL) VALUES ('HTDD002', 99.10, TO_DATE('06/05/2026','DD/MM/YYYY'), 'hate_speech', N'Ngôn ngữ xúc phạm nhắm vào cộng đồng người xem anime. Chứa từ ngữ tục tĩu và thái độ kỳ thị rõ ràng.', 'BL007');
INSERT INTO HE_THONG_DANH_DAU (MaHTDD, DoTinCay, NgayDanhDau, LoaiDanhDau, GhiChu, MaBL) VALUES ('HTDD003', 92.30, TO_DATE('07/05/2026','DD/MM/YYYY'), 'harrassment', N'Cố tình tiết lộ nội dung kết phim (spoiler) nhằm phá hỏng trải nghiệm người xem khác. Hành vi quấy rối cộng đồng.', 'BL008');
INSERT INTO HE_THONG_DANH_DAU (MaHTDD, DoTinCay, NgayDanhDau, LoaiDanhDau, GhiChu, MaBL) VALUES ('HTDD004', 98.80, TO_DATE('13/05/2026','DD/MM/YYYY'), 'spam', N'Tài khoản spam quảng cáo bán nick VIP giả trên nhiều phim. Phát hiện số điện thoại lạ và nội dung lặp lại liên tục.', 'BL016');
INSERT INTO HE_THONG_DANH_DAU (MaHTDD, DoTinCay, NgayDanhDau, LoaiDanhDau, GhiChu, MaBL) VALUES ('HTDD005', 88.60, TO_DATE('15/05/2026','DD/MM/YYYY'), 'fake_info', N'Đưa thông tin sai lệch về nội dung phim, gây hiểu nhầm rằng nền tảng phân loại phim không chính xác.', 'BL018');
INSERT INTO BINH_LUAN_KIEM_DUYET (MaBLKD, NoiDung, TrangThaiXL, MaBC, MaHTDD, MaTK_KDV) VALUES ('BLKD001', N'Xác nhận bình luận chứa link spam quảng cáo website ngoài. Đã ẩn bình luận và gửi cảnh báo lần 1 cho tài khoản.', N'Đã ẩn', 'BC001', 'HTDD001', 'TK009');
INSERT INTO BINH_LUAN_KIEM_DUYET (MaBLKD, NoiDung, TrangThaiXL, MaBC, MaHTDD, MaTK_KDV) VALUES ('BLKD002', N'Bình luận chứa ngôn từ thù ghét, xúc phạm cộng đồng anime. Vi phạm nghiêm trọng quy tắc cộng đồng. Đã ẩn vĩnh viễn.', N'Đã ẩn', 'BC002', 'HTDD002', 'TK007');
INSERT INTO BINH_LUAN_KIEM_DUYET (MaBLKD, NoiDung, TrangThaiXL, MaBC, MaHTDD, MaTK_KDV) VALUES ('BLKD003', N'Người dùng cố tình spoiler kết phim gây ảnh hưởng tiêu cực tới cộng đồng. Đã ẩn bình luận.', N'Đã ẩn', 'BC003', 'HTDD003', 'TK007');
INSERT INTO BINH_LUAN_KIEM_DUYET (MaBLKD, NoiDung, TrangThaiXL, MaBC, MaHTDD, MaTK_KDV) VALUES ('BLKD004', N'Tài khoản spam hàng loạt quảng cáo bán nick VIP giả. Đã ẩn toàn bộ bình luận và đề xuất khóa tài khoản.', N'Đã ẩn', 'BC004', 'HTDD004', 'TK009');
INSERT INTO BINH_LUAN_KIEM_DUYET (MaBLKD, NoiDung, TrangThaiXL, MaBC, MaHTDD, MaTK_KDV) VALUES ('BLKD005', N'Sau khi xem xét, nội dung bình luận có phần cường điệu nhưng không hoàn toàn sai. Phim có một số cảnh hành động mạnh. Tuy nhiên cách diễn đạt dễ gây hiểu lầm nên vẫn ẩn để tránh hoang mang.', N'Đã ẩn', 'BC005', 'HTDD005', 'TK008');
